{
protected:
    char *chars;
    string_buf *my_buf;
public:
    stringx(const stringx &);
    ~stringx();
};

class entity_anim_tree
{
public:
    void frame_advance(float);
};

class entity
{
public:
    entity_anim_tree *get_anim_tree(int);
};

enum { SURFER_LAST = 14 };
enum { ANIM_PRIMARY = 0 };

class FEEntityManager
{
public:
    enum { SA_IDLE, SA_SPECIAL_OCC, SA_OCC_1, SA_OCC_2, SA_SELECT, SA_TRICK };
    enum { BA_SPIN, BA_TRICK };

    entity *surfer_ent;
    char pad04[12];
    int surfer_anim_count;
    int current_surfer_index;
    char pad18[508];
    entity_anim_tree *surfer_tree;
    char pad218[12];
    int next_anim;
    int cur_anim;
    int cur_b_anim;
    int cur_trick_anim;

    void TrickPlay(int anim_id);
    void BoardPlay(int type, int anim_id = 0, float time = -1.0f);
    stringx makeString(int surfer, int anim);
    void Anim(stringx anim, float blend_time, bool loop, float time);
    void SurferPlay(int type, float time, int trick_num, int b_trick_num, bool no_blend);
};

void FEEntityManager::SurferPlay(int type, float time, int trick_num, int b_trick_num, bool no_blend)
{
	if(type == SA_TRICK)
	{
		TrickPlay(trick_num);
		BoardPlay(BA_TRICK, b_trick_num);
	}
	else if(current_surfer_index < SURFER_LAST)
	{
		float blend_time = 0.0f;

		if(surfer_ent)
		{
			Anim(makeString(current_surfer_index, type), blend_time, false, time);
			if (surfer_tree)
				surfer_ent->get_anim_tree(ANIM_PRIMARY)->frame_advance(0.0f);
		}

		cur_anim = type;

		surfer_anim_count++;
		if(surfer_anim_count == 6)
		{
			next_anim = SA_SPECIAL_OCC;
			surfer_anim_count = 0;
		}
		else next_anim = SA_IDLE;


		cur_trick_anim = -2;
	}
}
